export {
  backdropView,
  itemView,
  popupView,
  portalView,
  positionerView,
  rootView,
  separatorView,
  triggerView,
} from "../../../foldkit/ui/context-menu";
export type {
  BackdropViewConfig,
  ContextMenuStyle,
  ItemViewConfig,
  PartViewConfig,
  PortalViewConfig,
  RootViewConfig,
  TriggerViewConfig,
} from "../../../foldkit/ui/context-menu";

export {
  shadcnContextMenuBackdropClassName,
  shadcnContextMenuItemClassName,
  shadcnContextMenuPopupClassName,
  shadcnContextMenuPortalClassName,
  shadcnContextMenuPositionerClassName,
  shadcnContextMenuRootClassName,
  shadcnContextMenuSeparatorClassName,
  shadcnContextMenuTriggerClassName,
} from "./view";

export {
  contextMenuBackdropClassName as shadcnContextMenuBackdropClassName,
  contextMenuItemClassName as shadcnContextMenuItemClassName,
  contextMenuPopupClassName as shadcnContextMenuPopupClassName,
  contextMenuPortalClassName as shadcnContextMenuPortalClassName,
  contextMenuPositionerClassName as shadcnContextMenuPositionerClassName,
  contextMenuRootClassName as shadcnContextMenuRootClassName,
  contextMenuSeparatorClassName as shadcnContextMenuSeparatorClassName,
  contextMenuTriggerClassName as shadcnContextMenuTriggerClassName,
} from "../../../foldkit/ui/context-menu/view";

import { describe, expect, test } from "vitest";

import * as ContextMenu from "./index";

describe("shadcn Context Menu registry view", () => {
  test("reuses the Foldkit Context Menu view contract", () => {
    expect(ContextMenu.rootView).toBeTypeOf("function");
    expect(ContextMenu.triggerView).toBeTypeOf("function");
    expect(ContextMenu.itemView).toBeTypeOf("function");
    expect(ContextMenu.shadcnContextMenuPopupClassName).toContain("rounded");
  });
});
